{"path": "components/request-metadata.tsx", "content": "import { randomUUID } from 'node:crypto'
import { io } from 'next/cache'

export async function RequestMetadata() {
  // Exclude per-request values from the static shell; resolves immediately at request time.
  await io()

  const generatedAt = new Date().toISOString()
  const sample = Math.random()
  const requestId = randomUUID()

  return (
    <aside>
      Request {requestId} generated at {generatedAt} (sample {sample})
    </aside>
  )
}
"}

